const r=2**30;export const deep=(g,d)=>{if(d>=r)return g;const w=[];let t=g,v;for(;;){if(typeof t==="object"){if(t.next===undefined){const f=t.shift();t.push(r);t=f.apply(null,t);continue}const n=t.next(v);v=n.value;if(typeof v==="object"){if(!n.done)w.push(t);t=v;continue}}else v=t;if(w.length===0)return v;t=w.pop()}};const p=x=>Array.isArray(x)?x:x.$plain();export const listEq=(m,x,y,d)=>{if(d>=r)return s(m,x,y,true);const n=x.length;if(n!==y.length)return false;const a=p(x),b=p(y);for(let i=0;i<n;i++)if(!m(a[i],b[i],d))return false;return true};export const listCompare=(m,x,y,d)=>{if(d>=r)return s(m,x,y,false);const n=x.length,k=y.length,a=p(x),b=p(y);for(let i=0;i<n&&i<k;i++){const o=m(a[i],b[i],d);if(o!=="EQ")return o}return n===k?"EQ":n<k?"LT":"GT"};const s=function*(m,x,y,e){const n=x.length,k=y.length;if(e&&n!==k)return false;const a=p(x),b=p(y);for(let i=0;i<n&&i<k;i++){let o=m(a[i],b[i],r);if(typeof o==="object")o=yield o;if(e?!o:o!=="EQ")return o}return e?true:n===k?"EQ":n<k?"LT":"GT"};
